public class AccountTriggerHandler {
  public static void handleBeforeInsert(List<Account> records) {
    for (Account record : records) {
      record.Rating = 'Warm';
    }
  }
  public static void handleBeforeUpdate(Map<Id, Account> oldMap, List<Account> newRecords) {
    for (Account record : newRecords) {
      Account oldRecord = oldMap.get(record.Id);
      if (oldRecord != null && oldRecord.Name != record.Name) {
        record.Rating = 'Hot';
      }
    }
  }
}

trigger AccountTrigger on Account (before insert, before update) {
  if (Trigger.isBefore) {
    if (Trigger.isInsert) {
      AccountTriggerHandler.handleBeforeInsert(Trigger.new);
    }
    if (Trigger.isUpdate) {
      AccountTriggerHandler.handleBeforeUpdate(Trigger.oldMap, Trigger.new);
    }
  }
}

@isTest private class AccountTriggerHandlerTest {
  @isTest static void setsDefaultRatingOnInsert() {
    Account account = new Account(Name = 'Test');
    insert account;
    Account inserted = [SELECT Id, Name, Rating FROM Account WHERE Id = :account.Id];
    System.assertEquals('Warm', inserted.Rating);
  }
  @isTest static void setsHotRatingOnNameChange() {
    Account account = new Account(Name = 'Test');
    insert account;
    account.Name = 'Updated';
    update account;
    Account updated = [SELECT Id, Name, Rating FROM Account WHERE Id = :account.Id];
    System.assertEquals('Hot', updated.Rating);
  }
}
